func Call(ctx context.Context, req Request) (Reply, error) {
    reply := make(chan Reply, 1)              // buffered: replier never blocks
    ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
    defer cancel()
    bus <- Request{payload: req, reply: reply} // the channel IS the correlation
    select {
    case r := <-reply:
        return r, nil
    case <-ctx.Done():
        return Reply{}, ctx.Err()             // deadline or cancellation
    }
}

